import{_ as a,o as t,c as i,ae as s}from"./chunks/framework.C4zpkcTP.js";const p=JSON.parse('{"title":"AI Agent Skill","description":"Goravel Money is built for humans and AI agents. Install its agent skill so Claude Code, Codex, Cursor and other coding agents use the package correctly.","frontmatter":{"title":"AI Agent Skill","description":"Goravel Money is built for humans and AI agents. Install its agent skill so Claude Code, Codex, Cursor and other coding agents use the package correctly."},"headers":[],"relativePath":"goravel-money/ai-agent-skill.md","filePath":"goravel-money/ai-agent-skill.md"}'),n={name:"goravel-money/ai-agent-skill.md"};function o(l,e,r,h,d,c){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="ai-agent-skill" tabindex="-1">AI Agent Skill <a class="header-anchor" href="#ai-agent-skill" aria-label="Permalink to &quot;AI Agent Skill&quot;">​</a></h1><p>Goravel Money is built for humans and AI agents. These docs are written for developers, and the package also ships an agent skill: a short guide that teaches coding agents such as Claude Code, Codex and Cursor how to install, configure and use Goravel Money the way it&#39;s meant to be used.</p><h2 id="installing-the-skill" tabindex="-1">Installing the skill <a class="header-anchor" href="#installing-the-skill" aria-label="Permalink to &quot;Installing the skill&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> laranex/goravel-money</span></span></code></pre></div><p>Or copy <code>skills/goravel-money</code> from the <a href="https://github.com/laranex/goravel-money" target="_blank" rel="noreferrer">repository</a> into your project&#39;s <code>.claude/skills</code> or <code>.agents/skills</code> folder.</p><h2 id="what-the-skill-covers" tabindex="-1">What the skill covers <a class="header-anchor" href="#what-the-skill-covers" aria-label="Permalink to &quot;What the skill covers&quot;">​</a></h2><p>Work with money in a Goravel app using github.com/laranex/goravel-money/v4: the immutable <code>money.Money</code> value type, ORM column types, exact arithmetic, percentages, allocation, rounding and formatting with the correct precision for every currency.</p><p>It covers when to use the package, installing and configuring it, building money, calculating, formatting and serializing, storing amounts in the database, handling errors, testing your app and what to avoid. It is written from the package source and kept in the repository next to the code, so agents follow the same API, configuration and conventions these docs describe.</p><h2 id="keeping-it-current" tabindex="-1">Keeping it current <a class="header-anchor" href="#keeping-it-current" aria-label="Permalink to &quot;Keeping it current&quot;">​</a></h2><p>The skill lives in the package repository and is versioned with it, so it always describes the release you install. When you update Goravel Money, update the skill the same way you installed it.</p>',10)])])}const u=a(n,[["render",o]]);export{p as __pageData,u as default};
